using Aow.Convert;

namespace Aow.Formats.Tests;

/// <summary>
/// Every generated fixture case of aowconv check, one test each. Cases that read the installed
/// game skip when it is absent. The others are generated by code and always run.
/// </summary>
public sealed class FixtureTests : FormatsTest
{
    private static TheoryData<string> Names(bool usesGame)
    {
        var data = new TheoryData<string>();
        foreach (var c in Fixtures.All().Where(c => c.UsesGame == usesGame)) data.Add(c.Group + "/" + c.Name);
        return data;
    }

    public static TheoryData<string> GameCases() => Names(true);

    public static TheoryData<string> GeneratedCases() => Names(false);

    private static void Run(string name)
    {
        var c = Fixtures.All().Single(f => f.Group + "/" + f.Name == name);
        var outcome = c.Run();
        Assert.True(outcome.Matched, outcome.Detail);
    }

    [Theory]
    [MemberData(nameof(GeneratedCases))]
    public void GeneratedFixtureMatchesItsExpectedResult(string name) => Run(name);

    [GameTheory]
    [MemberData(nameof(GameCases))]
    public void GameFixtureMatchesItsExpectedResult(string name) => Run(name);

    [Fact]
    public void CaseNamesAreUniqueAndBothKindsExist()
    {
        var names = Fixtures.All().Select(c => c.Group + "/" + c.Name).ToList();
        Assert.Equal(names.Count, names.Distinct(StringComparer.Ordinal).Count());
        Assert.Equal(18, Fixtures.All().Count(c => !c.UsesGame));
    }
}
